import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"20、【观】 坤下巽上","description":"周易尚氏学 - 20、【观】 坤下巽上","frontmatter":{"title":"20、【观】 坤下巽上","description":"周易尚氏学 - 20、【观】 坤下巽上"},"headers":[],"relativePath":"zh/classics/shangshi/025.md","filePath":"zh/classics/shangshi/025.md"}'),h={name:"zh/classics/shangshi/025.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_20、【观】-坤下巽上" tabindex="-1">20、【观】 坤下巽上 <a class="header-anchor" href="#_20、【观】-坤下巽上" aria-label="Permalink to “20、【观】 坤下巽上”">​</a></h1><p>五得尊位。下临万民。民为庙堂。万民瞻仰。故曰观。易林以艮为观为视。象失传。详焦氏易治盖即本此也。国之大事。在把与戎。礼之可观。莫盛乎宗庙。宗庙之可观。莫盛乎祭祀。初漱降神也。马融云。进爵灌地以降神也。卦巽为白茅。茅在地上。坤水沃之。缩酒之象也。灌地降神。其诚敬之心。孚于神明。禺（右页）敬也。及至荐牲则扎简略。一孔子曰帝（左衣）自既灌而往者。吾不欲观之矣。与此义同也。</p><p>彖曰。大观在上。顺而巽。中正以观天下。观。漱而不荐。有孚禺（右页）若。下观而化也。观天之神道。而四时不忒。圣人以神道设教。而天下服矣。</p><p>坤为天下。天下化则服矣。此圣人所以以神道设教也。观亦候卦。故曰四时。临曰元亨利贞。亦四时也。</p><p>象曰。风行地上。观。先王以省方观民设教。</p><p>坤为方为民。艮为观。故曰省方。曰观民。巽为命。故曰教。先王巡狩四方。观风问俗。宣布教化。亦若风行地上也。</p><p>初六。童观，小人无咎。君子吝。</p><p>释文。马云童犹独也。郑云樨（左禾）也。而虞翻以艮为童。诂与郑同。按马说是也。太玄玄冲云。童寡有也。而易林每以坤为寡。初坤体。上无应。阴遇阴失类。孤寡极矣。故曰童观。其在小人。独行踽蹈（左同）。尚可无咎。若君子则狭隘为病矣。故吝。盖童之象不在艮。而在坤。初何以孤寡。则以上无应而行失类也。</p><h3 id="象曰。初六童观。小人道也。" tabindex="-1">象曰。初六童观。小人道也。 <a class="header-anchor" href="#象曰。初六童观。小人道也。" aria-label="Permalink to “象曰。初六童观。小人道也。”">​</a></h3><p>道行也。</p><p>六二。窥观。利女贞。</p><p>说文窥闪也。倾头门中视也。二应五。坤为门。二在门中。上窥九五。而坤为闭为羞。故羞缩不敢正视而窥观也。圣人取象之精。非注视卦象。不知其微妙如此也。窥观乃妾妇之行。故利女占。若在丈夫。则可丑矣。</p><h3 id="象曰。窥观女贞。亦可丑也。" tabindex="-1">象曰。窥观女贞。亦可丑也。 <a class="header-anchor" href="#象曰。窥观女贞。亦可丑也。" aria-label="Permalink to “象曰。窥观女贞。亦可丑也。”">​</a></h3><p>丑谓不庄</p><p>六三。观我生。进退。</p><p>凡我生皆谓应与。诗小雅。虽有兄弟。不如友生。易以阴阳相遇为朋友。故谓应与为我生。三应在上。故曰观我生。进退。上巽为进退。进退者上下也。三与上相上下。谓三宜进居上。上宜退居三。各当位也。故象曰不失道。</p><h3 id="象曰。观我生进退。未失道也。" tabindex="-1">象曰。观我生进退。未失道也。 <a class="header-anchor" href="#象曰。观我生进退。未失道也。" aria-label="Permalink to “象曰。观我生进退。未失道也。”">​</a></h3><p>道行也。</p><p>六四。观国之光。利用宾于王。</p><p>艮为国为光。四独近五。故曰观国之光。曰宾于王。王谓五。巽为利。言利于朝觐天子作宾王家也。巽为旅客。故曰宾。</p><h3 id="象曰。观国之光。尚宾也。" tabindex="-1">象曰。观国之光。尚宾也。 <a class="header-anchor" href="#象曰。观国之光。尚宾也。" aria-label="Permalink to “象曰。观国之光。尚宾也。”">​</a></h3><p>尚宾者。言宾于上也。</p><p>九五。观我生。君子无咎。</p><p>此我生谓二。五应在二。二坤为民。故象曰观民。九五为观之主。亦艮之主。艮为君子。下观万民。抚部（左血）教养。故无咎也。</p><h3 id="象曰。观我生。观民也。" tabindex="-1">象曰。观我生。观民也。 <a class="header-anchor" href="#象曰。观我生。观民也。" aria-label="Permalink to “象曰。观我生。观民也。”">​</a></h3><p>观民即指二。二坤为民。</p><p>上九。观其生。君子无咎。</p><p>诸家或释生为出为性为道。一人前后。诂即不同。似非。按其。谓五。生指三。上应在三。三坤体。坤民下附。皆五之民也。上贵而无位。高而无民。宜高尚其事矣。乃犹不忘情。欲应三而观其生焉。故象曰志未平。</p><h3 id="象曰。观其生。志未平也。" tabindex="-1">象曰。观其生。志未平也。 <a class="header-anchor" href="#象曰。观其生。志未平也。" aria-label="Permalink to “象曰。观其生。志未平也。”">​</a></h3><p>巽为志。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
